package main

import (
    "fmt"
    "image"
    "image/color"
    "image/jpeg"
    "os"
    "bytes"
)

func main(){
    // quick generate jpeg with known pixels
    w:=3
    h:=1
    img := image.NewRGBA(image.Rect(0,0,w,h))
    // black, gray127, white
    colors := []color.RGBA{{0,0,0,255},{127,127,127,255},{255,255,255,255}}
    for x,c := range colors {
        img.Set(x,0,c)
