package main

import (
    "image"
    "image/jpeg"
    "image/color"
    "os"
    "bytes"
    "fmt"
)

func writeJpeg(path string, w,h int, pixels []color.RGBA) {
    img := image.NewRGBA(image.Rect(0,0,w,h))
    idx:=0
    for y:=0;y<h;y++{
        for x:=0;x<w;x++{
            img.Set(x,y,pixels[idx])
            idx++
        }
    }
    var buf bytes.Buffer
    jpeg.Encode(&buf, img, &jpeg.Options{Quality:100})
    os.WriteFile(path, buf.Bytes(),0644)
    fmt.Printf("written %s %dx%d\n",path,w,h)
    f,_:=os.Open(path)
    defer f.Close()
    im,_:=jpeg.Decode(f)
    b:=im.Bounds()
    fmt.Printf("decoded bounds %v\n",b)
    for y:=b.Min.Y;y<b.Max.Y;y++{
        for x:=b.Min.X;x<b.Max.X;x++{
            r,g,b,_:=im.At(x,y).RGBA()
            fmt.Printf("(%d,%d):%d %d %d\n",x,y,r>>8,g>>8,b>>8)
        }
    }
}

func main(){
    writeJpeg("/tmp/test3x1.jpg",3,1, []color.RGBA{{0,0,0,255},{127,127,127,255},{255,255,255,255}})
    // 2x1 black white
    writeJpeg("/tmp/test2x1.jpg",2,1, []color.RGBA{{0,0,0,255},{255,255,255,255}})
    // test luminance thresholds
    // Create 16x1 with increasing gray 0,16,32,...255
    pix:=make([]color.RGBA,16)
    for i:=0;i<16;i++{
        v:=uint8(i*16 + 7) // mid?
        if i==15 {v=255}
        pix[i]=color.RGBA{v,v,v,255}
    }
    writeJpeg("/tmp/gray16.jpg",16,1, pix)
    // 2x1 red blue
    writeJpeg("/tmp/rb.jpg",2,1, []color.RGBA{{255,0,0,255},{0,0,255,255}})
    // 1x2 vertical
    writeJpeg("/tmp/test1x2.jpg",1,2, []color.RGBA{{0,0,0,255},{255,255,255,255}})
}
