    // print row values sample every barW/2
    for x:=0;x<w;x+=barW{
        r,g,bb,_:=im.At(x,h/2).RGBA()
        _=g;_=bb
        fmt.Printf("x%d=%d ",x,r>>8)
    }
    fmt.Println()
}

