package main

import (
    "fmt"
    "os"
    "image"
    "image/jpeg"
    "bytes"
    "math"
)

func lum(r,g,b uint8, rw,gw,bw float64) uint8 {
    return uint8(rw*float64(r) + gw*float64(g) + bw*float64(b) + 0.5)
}

func main(){
    if len(os.Args)<2 {fmt.Println("usage proto.go <jpg> --width=10 etc"); return}
    // quick proto: hardcode width 10, chars default, no invert
    path:=os.Args[1]
    f,_:=os.Open(path)
    defer f.Close()
    img,err:=jpeg.Decode(f)
    if err!=nil{fmt.Printf("decode err %v\n",err); return}
    bounds:=img.Bounds()
    srcW:=bounds.Dx()
    srcH:=bounds.Dy()
    outW:=10
    outH:= int(math.Round(float64(outW)*float64(srcH)/float64(srcW)*0.5))
    if outH<1 {outH=1}
    fmt.Printf("src %dx%d out %dx%d\n",srcW,srcH,outW,outH)
    chars:=`   ...',;:clodxkO0KXNWM`
    // for each out y,x sample
    for y:=0;y<outH;y++{
        for x:=0;x<outW;x++{
            srcX:= x*srcW/outW
            srcY:= y*srcH/outH
            // Alternative middle?
            // srcX = int(float64(x)+0.5)*float64(srcW)/float64(outW))
            r,g,b,_:=img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY).RGBA()
            // need to handle YCbCr vs Gray: At returns 16-bit
            rr:=uint8(r>>8); gg:=uint8(g>>8); bb:=uint8(b>>8)
            l:=lum(rr,gg,bb,0.2989,0.5866,0.1145)
            idx:= (int(l)* (len(chars)-1) + 127)/255
            fmt.Printf("%c",chars[idx])
        }
        fmt.Println()
    }
    // also try alternative sampling middle
    fmt.Println("--- middle sampling ---")
    for y:=0;y<outH;y++{
        for x:=0;x<outW;x++{
            srcX:= int((float64(x)+0.5)*float64(srcW)/float64(outW))
            if srcX>=srcW {srcX=srcW-1}
            srcY:= int((float64(y)+0.5)*float64(srcH)/float64(outH))
            if srcY>=srcH {srcY=srcH-1}
            r,g,b,_:=img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY).RGBA()
            rr:=uint8(r>>8); gg:=uint8(g>>8); bb:=uint8(b>>8)
            l:=lum(rr,gg,bb,0.2989,0.5866,0.1145)
            idx:= (int(l)* (len(chars)-1) + 127)/255
            fmt.Printf("%c",chars[idx])
        }
        fmt.Println()
    }
}
