                func(y,h,oh,_ int)int{return (y*h + oh/2)/oh},
            )
            simCeil:=simulate(lut, ow,h, chars,
                func(x,w,ow,_ int)int{return (x*w + w -1)/ow}, // ??
                func(y,h,oh,_ int)int{return (y*h + h -1)/oh},
            )
            fmt.Printf("    floor %q middle %q round %q ceil %q\n",simFloor,simMiddle,simRound,simCeil)
        }
        fmt.Println("---")
    }
}
