      --blue=N.N    Set RGB to grayscale conversion weight, default is 0.1145
  -b, --border      Print a border around the output image.
      --chars=...   Select character palette used to paint the image.
                    Leftmost character corresponds to black pixel, right-
                    most to white.  Minimum two characters must be specified.
      --clear       Clears screen before drawing each output image.
      --colors      Use ANSI colors in output.
  -d, --debug       Print additional debug information.
      --fill        When used with --color and/or --html, color each character's
                    background color.
  -x, --flipx       Flip image in X direction.
  -y, --flipy       Flip image in Y direction.
  -f, --term-fit    Use the largest image dimension that fits in your terminal
                    display with correct aspect ratio.
      --term-height Use terminal display height.
      --term-width  Use terminal display width.
  -z, --term-zoom   Use terminal display dimension for output.
      --grayscale   Convert image to grayscale when using --html or --colors
      --green=N.N   Set RGB to grayscale conversion weight, default is 0.5866
      --height=N    Set output height, calculate width from aspect ratio.
  -h, --help        Print program help.
      --html        Produce strict XHTML 1.0 output.
      --html-fill   Same as --fill (will be phased out)
      --html-fontsize=N   Set fontsize to N pt, default is 4.
      --html-no-bold      Do not use bold characters with HTML output
      --html-raw    Output raw HTML codes, i.e. without the <head> section etc.
      --html-title=...  Set HTML output title
  -i, --invert      Invert output image.  Use if your display has a dark
                    background.
      --background=dark   These are just mnemonics whether to use --invert
      --background=light  or not.  If your console has light characters on
                    a dark background, use --background=dark.
      --output=...  Write output to file.
      --red=N.N     Set RGB to grayscale conversion weight, default 0.2989f.
      --size=WxH    Set output width and height.
  -v, --verbose     Verbose output.
  -V, --version     Print program version.
      --width=N     Set output width, calculate height from ratio.

  The default mode is ` + "`jp2a --term-fit --background=dark'." + `
  See the man-page for jp2a for more detailed help text.

Project homepage on https://github.com/cslarsen/jp2a
Report bugs to <csl@csl.name>`

type Config struct {
	widthSet bool
	width int
	heightSet bool
	height int
	sizeSet bool
	sizeW int
	sizeH int
	chars string
	charsSet bool
	invert bool
	border bool
	colors bool
	fill bool
	flipx bool
	flipy bool
	termFit bool
	termWidth bool
	termHeight bool
	termZoom bool
	grayscale bool
	html bool
	htmlRaw bool
	htmlNoBold bool
	htmlFontSize int
	htmlFontSizeSet bool
	htmlTitle string
	htmlTitleSet bool
	verbose bool
	debug bool
	clear bool
	output string
	outputSet bool
	red float64
	redSet bool
	green float64
	greenSet bool
	blue float64
	blueSet bool
}

func printHelp() {
	fmt.Fprintln(os.Stderr, helpStr)
}

func printVersion() {
	fmt.Println(versionStr)
}

func printVersionToStderr() {
	fmt.Fprintln(os.Stderr, versionStr)
	fmt.Fprintln(os.Stderr, "")
	fmt.Fprintln(os.Stderr, helpStr)
}

func getTerminalSize() (int, int) {
	colsStr := os.Getenv("COLUMNS")
	linesStr := os.Getenv("LINES")
	cols, err1 := strconv.Atoi(colsStr)
	lines, err2 := strconv.Atoi(linesStr)
	if err1 != nil || cols <= 0 {
		cols = 80
	}
	if err2 != nil || lines <= 0 {
		lines = 24
	}
	// Also try to get from syscall if available? Use 80x24 fallback
	return cols, lines
}

func parseArgs(args []string) (Config, []string, error) {
	cfg := Config{
		chars: "   ...',;:clodxkO0KXNWM",
		red: 0.2989,
		green: 0.5866,
		blue: 0.1145,
		htmlFontSize: 4,
		htmlTitle: "jp2a converted image",
	}
	var files []string
	// To handle invert/background toggling in order, we need to process sequentially
	// For other options, last wins, but we can just set as we go
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-" {
			files = append(files, arg)
			continue
		}
		if arg == "-b" || arg == "--border" {
			cfg.border = true
			continue
		}
		if arg == "-i" || arg == "--invert" {
			cfg.invert = !cfg.invert
			continue
		}
		if arg == "-x" || arg == "--flipx" {
			cfg.flipx = true
			continue
		}
		if arg == "-y" || arg == "--flipy" {
			cfg.flipy = true
			continue
		}
		if arg == "-f" || arg == "--term-fit" {
			cfg.termFit = true
			continue
		}
		if arg == "-z" || arg == "--term-zoom" {
			cfg.termZoom = true
			continue
		}
		if arg == "-v" || arg == "--verbose" {
			cfg.verbose = true
			continue
		}
		if arg == "-d" || arg == "--debug" {
			cfg.debug = true
			continue
		}
		if arg == "-h" || arg == "--help" {
			printHelp()
			os.Exit(0)
		}
		if arg == "-V" || arg == "--version" {
			printVersion()
			os.Exit(0)
		}
		if strings.HasPrefix(arg, "--background=") {
			val := strings.TrimPrefix(arg, "--background=")
			if val == "dark" {
				cfg.invert = false
			} else if val == "light" {
				cfg.invert = true
			} else {
				return cfg, nil, fmt.Errorf("Unknown option %s", arg)
			}
			continue
		}
		if strings.HasPrefix(arg, "--chars=") {
			val := strings.TrimPrefix(arg, "--chars=")
			// Keep as is, including spaces. Need to handle empty?
			cfg.chars = val
			cfg.charsSet = true
			continue
		}
		if arg == "--colors" {
			cfg.colors = true
			continue
		}
		if arg == "--fill" || arg == "--html-fill" {
			cfg.fill = true
			continue
		}
		if arg == "--grayscale" {
			cfg.grayscale = true
			continue
		}
		if strings.HasPrefix(arg, "--green=") {
			val := strings.TrimPrefix(arg, "--green=")
			f, err := strconv.ParseFloat(val, 64)
			if err != nil {
				return cfg, nil, fmt.Errorf("Unknown option %s", arg)
			}
			cfg.green = f
			cfg.greenSet = true
			continue
		}
		if strings.HasPrefix(arg, "--height=") {
			val := strings.TrimPrefix(arg, "--height=")
			// check if val is integer
			if val == "" {
				return cfg, nil, fmt.Errorf("Unknown option %s", arg)
			}
			// try parse
			n, err := strconv.Atoi(val)
			if err != nil {
				return cfg, nil, fmt.Errorf("Unknown option %s", arg)
			}
			cfg.height = n
			cfg.heightSet = true
			continue
		}
		if arg == "--html" {
			cfg.html = true
			continue
		}
		if arg == "--html-no-bold" {
			cfg.htmlNoBold = true
			continue
		}
		if arg == "--html-raw" {
			cfg.htmlRaw = true
			continue
		}
		if strings.HasPrefix(arg, "--html-fontsize=") {
			val := strings.TrimPrefix(arg, "--html-fontsize=")
			n, err := strconv.Atoi(val)
			if err != nil {
				return cfg, nil, fmt.Errorf("Unknown option %s", arg)
			}
			cfg.htmlFontSize = n
			cfg.htmlFontSizeSet = true
			continue
		}
		if strings.HasPrefix(arg, "--html-title=") {
			val := strings.TrimPrefix(arg, "--html-title=")
			cfg.htmlTitle = val
			cfg.htmlTitleSet = true
			continue
		}
		if strings.HasPrefix(arg, "--output=") {
			val := strings.TrimPrefix(arg, "--output=")
			cfg.output = val
			cfg.outputSet = true
			continue
		}
		if strings.HasPrefix(arg, "--red=") {
			val := strings.TrimPrefix(arg, "--red=")
			f, err := strconv.ParseFloat(val, 64)
			if err != nil {
				return cfg, nil, fmt.Errorf("Unknown option %s", arg)
			}
			cfg.red = f
			cfg.redSet = true
			continue
		}
		if strings.HasPrefix(arg, "--blue=") {
			val := strings.TrimPrefix(arg, "--blue=")
			f, err := strconv.ParseFloat(val, 64)
			if err != nil {
				return cfg, nil, fmt.Errorf("Unknown option %s", arg)
			}
			cfg.blue = f
			cfg.blueSet = true
			continue
		}
		if strings.HasPrefix(arg, "--size=") {
			val := strings.TrimPrefix(arg, "--size=")
			parts := strings.Split(val, "x")
			if len(parts) != 2 {
				return cfg, nil, fmt.Errorf("Unknown option %s", arg)
			}
			w, err1 := strconv.Atoi(parts[0])
			h, err2 := strconv.Atoi(parts[1])
			if err1 != nil || err2 != nil {
				return cfg, nil, fmt.Errorf("Unknown option %s", arg)
			}
			cfg.sizeW = w
			cfg.sizeH = h
			cfg.sizeSet = true
			continue
		}
		if strings.HasPrefix(arg, "--width=") {
			val := strings.TrimPrefix(arg, "--width=")
			if val == "" {
				return cfg, nil, fmt.Errorf("Unknown option %s", arg)
			}
			n, err := strconv.Atoi(val)
			if err != nil {
				return cfg, nil, fmt.Errorf("Unknown option %s", arg)
			}
			cfg.width = n
			cfg.widthSet = true
			continue
		}
		if arg == "--term-width" {
			cfg.termWidth = true
			continue
		}
		if arg == "--term-height" {
			cfg.termHeight = true
			continue
		}
		if arg == "--clear" {
			cfg.clear = true
			continue
		}
		// Check for unknown long option
		if strings.HasPrefix(arg, "--") {
			return cfg, nil, fmt.Errorf("Unknown option %s", arg)
		}
		// Check for unknown short option
		if strings.HasPrefix(arg, "-") {
			return cfg, nil, fmt.Errorf("Unknown option %s", arg)
		}
		// Otherwise it's a file
		files = append(files, arg)
	}
	return cfg, files, nil
}

func validateConfig(cfg Config) error {
	if cfg.charsSet && len(cfg.chars) < 2 {
		return fmt.Errorf("You must specify at least two characters in --chars.")
	}
	// Check weights sum to 1.0
	sum := cfg.red + cfg.green + cfg.blue
	// Use tolerance 0.0001? Original checks exact 1.0 with floating, but we use tolerance
	if cfg.redSet || cfg.greenSet || cfg.blueSet {
		if sum < 0.9999 || sum > 1.0001 {
			return fmt.Errorf("Weights RED + GREEN + BLUE must equal 1.0")
		}
	}
	// Check width/height/size validity
	if cfg.widthSet && cfg.width < 0 {
		return fmt.Errorf("Invalid width or height specified")
	}
	if cfg.heightSet && cfg.height < 0 {
		return fmt.Errorf("Invalid width or height specified")
	}
	if cfg.heightSet && cfg.height == 0 {
		return fmt.Errorf("Invalid width or height specified")
	}
	// width 0 is allowed? Original allows 0 for width, but not for height. So we allow width 0.
	if cfg.sizeSet {
		if cfg.sizeW <= 0 || cfg.sizeH <= 0 {
			return fmt.Errorf("Invalid width or height specified")
		}
	}
	// For term options, check TERM
	termNeeded := cfg.termFit || cfg.termWidth || cfg.termHeight || cfg.termZoom
	// Also default termFit if no explicit dimensions
	if !cfg.widthSet && !cfg.heightSet && !cfg.sizeSet && !termNeeded {
		termNeeded = true
	}
	if termNeeded {
		if os.Getenv("TERM") == "" {
			return fmt.Errorf("Environment variable TERM not set.")
		}
	}
	return nil
}

func computeDimensions(cfg Config, srcW, srcH int) (int,int) {
	termCols, termLines := getTerminalSize()
	termHeight := termLines - 1
	if termHeight < 1 {
		termHeight = termLines
	}
	// Handle size
	if cfg.sizeSet {
		return cfg.sizeW, cfg.sizeH
	}
	// Handle termZoom
	if cfg.termZoom {
		return termCols, termHeight
	}
	// Handle termWidth
	if cfg.termWidth {
		w := termCols
		h := int(float64(w)*float64(srcH)/float64(srcW)*0.5 + 0.5)
		if h < 1 {
			h = 1
		}
		return w, h
	}
	// Handle termHeight
	if cfg.termHeight {
		h := termHeight
		w := int(float64(h)*float64(srcW)/float64(srcH)*2 + 0.5)
		if w < 1 {
			w = 1
		}
		return w, h
	}
	// Handle width and height both set
	if cfg.widthSet && cfg.heightSet {
		return cfg.width, cfg.height
	}
	if cfg.widthSet {
		w := cfg.width
		// width 0 is special: use termHeight? Actually for width 0 with TERM, we saw it gave width 0 height 23 (termHeight)
		// That suggests width 0 means use 0 width but height from term?
		// But we will handle width 0 as is: compute height as if width 0? Then height would be 0? But observed height 23, so width 0 triggers termFit?
		// Let's handle: if width ==0, then use termFit logic?
		if w == 0 {
			// Fall back to termFit
			// Compute termFit
			w1 := termCols
			h1 := int(float64(w1)*float64(srcH)/float64(srcW)*0.5 + 0.5)
			if h1 < 1 { h1 = 1 }
			h2 := termHeight
			w2 := int(float64(h2)*float64(srcW)/float64(srcH)*2 + 0.5)
			if w2 < 1 { w2 = 1 }
			// Choose largest that fits
			fits1 := w1 <= termCols && h1 <= termHeight
			fits2 := w2 <= termCols && h2 <= termHeight
			if fits1 && fits2 {
				if w1*h1 > w2*h2 {
					return w1, h1
				} else {
					return w2, h2
				}
			} else if fits1 {
				return w1, h1
			} else if fits2 {
				return w2, h2
			} else {
				// fallback to smaller
				if w1*h1 < w2*h2 {
					return w1, h1
				} else {
					return w2, h2
				}
			}
		}
		h := int(float64(w)*float64(srcH)/float64(srcW)*0.5 + 0.5)
		if h < 1 {
			h = 1
		}
		return w, h
	}
	if cfg.heightSet {
		h := cfg.height
		w := int(float64(h)*float64(srcW)/float64(srcH)*2 + 0.5)
		if w < 1 {
			w = 1
		}
		return w, h
	}
	// Default termFit
	w1 := termCols
	h1 := int(float64(w1)*float64(srcH)/float64(srcW)*0.5 + 0.5)
	if h1 < 1 { h1 = 1 }
	h2 := termHeight
	w2 := int(float64(h2)*float64(srcW)/float64(srcH)*2 + 0.5)
	if w2 < 1 { w2 = 1 }
	fits1 := w1 <= termCols && h1 <= termHeight
	fits2 := w2 <= termCols && h2 <= termHeight
	if fits1 && fits2 {
		if w1*h1 > w2*h2 {
			return w1, h1
		} else {
			return w2, h2
		}
	} else if fits1 {
		return w1, h1
	} else if fits2 {
		return w2, h2
	} else {
		if w1*h1 < w2*h2 {
			return w1, h1
		} else {
			return w2, h2
		}
	}
}

func processImage(path string, cfg Config, outW, outH int, img image.Image) string {
	bounds := img.Bounds()
	srcW := bounds.Dx()
	srcH := bounds.Dy()
	// Prepare palette
	palette := cfg.chars
	n := len(palette)
	// For each output pixel, sample
	var buf bytes.Buffer
	// Handle border: we will generate inner content first, then wrap
	innerLines := make([]string, outH)
	for y := 0; y < outH; y++ {
		var line bytes.Buffer
		for x := 0; x < outW; x++ {
			srcX := x * srcW / outW
			srcY := y * srcH / outH
			if srcX >= srcW { srcX = srcW - 1 }
			if srcY >= srcH { srcY = srcH - 1 }
			if cfg.flipx {
				srcX = srcW - 1 - srcX
			}
			if cfg.flipy {
				srcY = srcH - 1 - srcY
			}
			// Get pixel
			r, g, b, _ := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY).RGBA()
			rr := uint8(r >> 8)
			gg := uint8(g >> 8)
			bb := uint8(b >> 8)
			var lum uint8
			// If image is grayscale (we could detect, but use weights)
			lum = uint8(cfg.red*float64(rr) + cfg.green*float64(gg) + cfg.blue*float64(bb) + 0.5)
			idx := (int(lum)*(n-1) + 127) / 255
			if idx < 0 { idx = 0 }
			if idx >= n { idx = n - 1 }
			if cfg.invert {
				idx = n - 1 - idx
			}
			ch := palette[idx]
			// Handle colors
			if cfg.colors {
				// For HTML, we will handle later, for terminal, add ANSI
				if cfg.html {
					// For HTML, we need to handle per pixel color
					// Determine color hex
					var hexColor string
					if cfg.grayscale {
						hexColor = fmt.Sprintf("#%02x%02x%02x", lum, lum, lum)
					} else {
						// Use original RGB, but if image is grayscale, lum is same as RGB
						// For YCbCr, we have rr,gg,bb
						hexColor = fmt.Sprintf("#%02x%02x%02x", rr, gg, bb)
					}
					// For fill, also need background
					if cfg.fill {
						// Text color is half brightness, background is hexColor
						// Compute half lum for text?
						// For html fill, text color is darker version
						// We need to compute text color as half of lum or half of RGB?
						// For simplicity, use lum/2 for grayscale, or for color, use half of each channel
						var textColor string
						if cfg.grayscale {
							half := lum / 2
							// Actually observed for #dadada (218) text #6d6d6d (109) which is lum/2
							// So textColor is half lum
							textColor = fmt.Sprintf("#%02x%02x%02x", half, half, half)
						} else {
							tr := rr / 2
							tg := gg / 2
							tb := bb / 2
							// But observed for color, text color was #6d6d6d for #dadada, which is gray half, not color half?
							// For color case, they may use gray for text? Let's check: For logo gray with fill, text was gray. For color image with fill, what would text be?
							// We need to decide: For fill with html and colors, text color is gray half? Or is it half of original color?
							// Let's assume half of original color
							textColor = fmt.Sprintf("#%02x%02x%02x", tr, tg, tb)
						}
						line.WriteString(fmt.Sprintf("<span style='color:%s; background-color:%s;'>%c</span>", textColor, hexColor, ch))
					} else {
						line.WriteString(fmt.Sprintf("<span style='color:%s;'>%c</span>", hexColor, ch))
					}
				} else {
					// Terminal colors
					// For grayscale or --grayscale, use white (37) or bold?
					// For terminal with colors and grayscale, use 37
					if cfg.grayscale {
						// Use white
						line.WriteString(fmt.Sprintf("\x1b[37m%c\x1b[0m", ch))
					} else {
						// Check if image is grayscale by seeing if rr==gg==bb?
						// For logo, it's grayscale, but we still want to output colors? For logo, colors gave bold, not 37.
						// Let's detect if image is color: if src has color components 3, then use RGB mapping, else use grayscale handling
						// We need to know if image is color: we can check if img is *image.Gray vs *image.YCbCr etc.
						// For now, assume if rr==gg && gg==bb, treat as grayscale
						if rr == gg && gg == bb {
							// Grayscale: use bold for bright?
							if lum > 127 {
								line.WriteString(fmt.Sprintf("\x1b[1m%c\x1b[0m", ch))
							} else {
								line.WriteByte(ch)
							}
						} else {
							// Color: map to 8 colors
							// Determine ANSI code
							// Use 30 + (r>127) + (g>127)*2 + (b>127)*4
							code := 30
							if rr > 127 { code += 1 }
							if gg > 127 { code += 2 }
							if bb > 127 { code += 4 }
							// For bright, use 1m bold? Original for red gave 31 without bold, for yellow 33, etc.
							// We'll just use code without bold, but for white, use 37
							line.WriteString(fmt.Sprintf("\x1b[%dm%c\x1b[0m", code, ch))
						}
					}
				}
			} else {
				// No colors, just char
				// Need to handle HTML escaping for html mode without colors: escape &, <, >, etc? Original may escape? For chars like <, >, &, they need to be escaped in HTML.
				// The default palette doesn't contain those, but user may provide.
				// For html without colors, we should escape.
				if cfg.html {
					// Escape for HTML
					switch ch {
					case '&':
						line.WriteString("&amp;")
					case '<':
						line.WriteString("&lt;")
					case '>':
						line.WriteString("&gt;")
					case ' ':
						// For HTML, spaces need to be preserved? In <pre>, spaces are preserved.
						// But for colors, they use &nbsp; for spaces? Let's see: For html with colors, spaces were &nbsp;?
						// In earlier test for html with colors, we didn't see spaces, but for html without colors, spaces are just spaces.
						line.WriteByte(ch)
					default:
						line.WriteByte(ch)
					}
				} else {
					line.WriteByte(ch)
				}
			}
		}
		innerLines[y] = line.String()
	}
	// Handle border
	if cfg.border {
		// For html, border is inside <pre> with + and | etc, but with html colors, border should not be colored?
		// Original for html with border and colors, border was not colored, just plain + and |
		// So we will add border after generating inner lines, without colors for border
		// For terminal with colors, border also not colored
		top := "+" + strings.Repeat("-", outW) + "+"
		bottom := top
		newLines := make([]string, 0, outH+2)
		newLines = append(newLines, top)
		for _, l := range innerLines {
			// l may contain ANSI codes or HTML spans, need to wrap with |...|
			// For html with colors, l contains spans, we need to wrap with | and |
			newLines = append(newLines, "|"+l+"|")
		}
		newLines = append(newLines, bottom)
		innerLines = newLines
		outH += 2
		outW += 2
	}
	// Now handle html wrapping
	if cfg.html && !cfg.htmlRaw {
		var htmlBuf bytes.Buffer
		htmlBuf.WriteString("<?xml version='1.0' encoding='ISO-8859-1'?>\n")
		htmlBuf.WriteString("<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n")
		htmlBuf.WriteString("<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n")
		htmlBuf.WriteString("<head>\n")
		htmlBuf.WriteString(fmt.Sprintf("<title>%s</title>\n", cfg.htmlTitle))
		htmlBuf.WriteString("<style type='text/css'>\n")
		if cfg.invert {
			htmlBuf.WriteString("body {\n   background-color: white;\n}\n")
		} else {
			htmlBuf.WriteString("body {\nbackground-color: black;\n}\n")
		}
		htmlBuf.WriteString(".ascii {\n")
		htmlBuf.WriteString("   font-family: Courier;\n")
		if !cfg.colors {
			if cfg.invert {
				htmlBuf.WriteString("   color: black;\n")
			} else {
				htmlBuf.WriteString("   color: white;\n")
			}
		}
