		}
	}
	// For term options, check TERM
	termNeeded := cfg.termFit || cfg.termWidth || cfg.termHeight || cfg.termZoom
	// Also default termFit if no explicit dimensions
	if !cfg.widthSet && !cfg.heightSet && !cfg.sizeSet && !termNeeded {
		termNeeded = true
	}
	if termNeeded {
		if os.Getenv("TERM") == "" {
			return fmt.Errorf("Environment variable TERM not set.")
		}
	}
	return nil
}

func computeDimensions(cfg Config, srcW, srcH int) (int,int) {
	termCols, termLines := getTerminalSize()
	termHeight := termLines - 1
	if termHeight < 1 {
		termHeight = termLines
	}
	// Handle size
	if cfg.sizeSet {
		return cfg.sizeW, cfg.sizeH
	}
	// Handle termZoom
	if cfg.termZoom {
		return termCols, termHeight
	}
	// Handle termWidth
	if cfg.termWidth {
		w := termCols
		h := int(float64(w)*float64(srcH)/float64(srcW)*0.5 + 0.5)
		if h < 1 {
			h = 1
		}
		return w, h
	}
	// Handle termHeight
	if cfg.termHeight {
		h := termHeight
		w := int(float64(h)*float64(srcW)/float64(srcH)*2 + 0.5)
		if w < 1 {
			w = 1
		}
		return w, h
	}
	// Handle width and height both set
	if cfg.widthSet && cfg.heightSet {
		return cfg.width, cfg.height
	}
	if cfg.widthSet {
		w := cfg.width
		// width 0 is special: use termHeight? Actually for width 0 with TERM, we saw it gave width 0 height 23 (termHeight)
		// That suggests width 0 means use 0 width but height from term?
		// But we will handle width 0 as is: compute height as if width 0? Then height would be 0? But observed height 23, so width 0 triggers termFit?
		// Let's handle: if width ==0, then use termFit logic?
		if w == 0 {
			// Fall back to termFit
			// Compute termFit
			w1 := termCols
			h1 := int(float64(w1)*float64(srcH)/float64(srcW)*0.5 + 0.5)
			if h1 < 1 { h1 = 1 }
			h2 := termHeight
			w2 := int(float64(h2)*float64(srcW)/float64(srcH)*2 + 0.5)
			if w2 < 1 { w2 = 1 }
			// Choose largest that fits
			fits1 := w1 <= termCols && h1 <= termHeight
			fits2 := w2 <= termCols && h2 <= termHeight
			if fits1 && fits2 {
				if w1*h1 > w2*h2 {
					return w1, h1
				} else {
					return w2, h2
				}
			} else if fits1 {
				return w1, h1
			} else if fits2 {
				return w2, h2
			} else {
				// fallback to smaller
				if w1*h1 < w2*h2 {
					return w1, h1
				} else {
					return w2, h2
				}
			}
		}
		h := int(float64(w)*float64(srcH)/float64(srcW)*0.5 + 0.5)
		if h < 1 {
			h = 1
		}
		return w, h
	}
	if cfg.heightSet {
		h := cfg.height
		w := int(float64(h)*float64(srcW)/float64(srcH)*2 + 0.5)
		if w < 1 {
			w = 1
		}
		return w, h
	}
	// Default termFit
	w1 := termCols
	h1 := int(float64(w1)*float64(srcH)/float64(srcW)*0.5 + 0.5)
	if h1 < 1 { h1 = 1 }
	h2 := termHeight
	w2 := int(float64(h2)*float64(srcW)/float64(srcH)*2 + 0.5)
	if w2 < 1 { w2 = 1 }
	fits1 := w1 <= termCols && h1 <= termHeight
	fits2 := w2 <= termCols && h2 <= termHeight
	if fits1 && fits2 {
		if w1*h1 > w2*h2 {
			return w1, h1
		} else {
			return w2, h2
		}
	} else if fits1 {
		return w1, h1
	} else if fits2 {
		return w2, h2
	} else {
		if w1*h1 < w2*h2 {
			return w1, h1
		} else {
			return w2, h2
		}
	}
}

func processImage(path string, cfg Config, outW, outH int, img image.Image) string {
	bounds := img.Bounds()
	srcW := bounds.Dx()
	srcH := bounds.Dy()
	// Prepare palette
	palette := cfg.chars
	n := len(palette)
	// For each output pixel, sample
	var buf bytes.Buffer
	// Handle border: we will generate inner content first, then wrap
	innerLines := make([]string, outH)
	for y := 0; y < outH; y++ {
		var line bytes.Buffer
		for x := 0; x < outW; x++ {
			srcX := x * srcW / outW
			srcY := y * srcH / outH
			if srcX >= srcW { srcX = srcW - 1 }
			if srcY >= srcH { srcY = srcH - 1 }
			if cfg.flipx {
				srcX = srcW - 1 - srcX
			}
			if cfg.flipy {
				srcY = srcH - 1 - srcY
			}
			// Get pixel
			r, g, b, _ := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY).RGBA()
			rr := uint8(r >> 8)
			gg := uint8(g >> 8)
			bb := uint8(b >> 8)
			var lum uint8
			// If image is grayscale (we could detect, but use weights)
			lum = uint8(cfg.red*float64(rr) + cfg.green*float64(gg) + cfg.blue*float64(bb) + 0.5)
			idx := (int(lum)*(n-1) + 127) / 255
			if idx < 0 { idx = 0 }
			if idx >= n { idx = n - 1 }
			if cfg.invert {
				idx = n - 1 - idx
			}
			ch := palette[idx]
			// Handle colors
			if cfg.colors {
				// For HTML, we will handle later, for terminal, add ANSI
				if cfg.html {
					// For HTML, we need to handle per pixel color
					// Determine color hex
					var hexColor string
					if cfg.grayscale {
						hexColor = fmt.Sprintf("#%02x%02x%02x", lum, lum, lum)
					} else {
						// Use original RGB, but if image is grayscale, lum is same as RGB
						// For YCbCr, we have rr,gg,bb
						hexColor = fmt.Sprintf("#%02x%02x%02x", rr, gg, bb)
					}
					// For fill, also need background
					if cfg.fill {
						// Text color is half brightness, background is hexColor
						// Compute half lum for text?
						// For html fill, text color is darker version
						// We need to compute text color as half of lum or half of RGB?
						// For simplicity, use lum/2 for grayscale, or for color, use half of each channel
						var textColor string
						if cfg.grayscale {
							half := lum / 2
							// Actually observed for #dadada (218) text #6d6d6d (109) which is lum/2
							// So textColor is half lum
							textColor = fmt.Sprintf("#%02x%02x%02x", half, half, half)
						} else {
							tr := rr / 2
							tg := gg / 2
							tb := bb / 2
							// But observed for color, text color was #6d6d6d for #dadada, which is gray half, not color half?
							// For color case, they may use gray for text? Let's check: For logo gray with fill, text was gray. For color image with fill, what would text be?
							// We need to decide: For fill with html and colors, text color is gray half? Or is it half of original color?
							// Let's assume half of original color
							textColor = fmt.Sprintf("#%02x%02x%02x", tr, tg, tb)
						}
						line.WriteString(fmt.Sprintf("<span style='color:%s; background-color:%s;'>%c</span>", textColor, hexColor, ch))
					} else {
						line.WriteString(fmt.Sprintf("<span style='color:%s;'>%c</span>", hexColor, ch))
					}
				} else {
					// Terminal colors
					// For grayscale or --grayscale, use white (37) or bold?
					// For terminal with colors and grayscale, use 37
					if cfg.grayscale {
						// Use white
						line.WriteString(fmt.Sprintf("\x1b[37m%c\x1b[0m", ch))
					} else {
						// Check if image is grayscale by seeing if rr==gg==bb?
						// For logo, it's grayscale, but we still want to output colors? For logo, colors gave bold, not 37.
						// Let's detect if image is color: if src has color components 3, then use RGB mapping, else use grayscale handling
						// We need to know if image is color: we can check if img is *image.Gray vs *image.YCbCr etc.
						// For now, assume if rr==gg && gg==bb, treat as grayscale
						if rr == gg && gg == bb {
							// Grayscale: use bold for bright?
							if lum > 127 {
								line.WriteString(fmt.Sprintf("\x1b[1m%c\x1b[0m", ch))
							} else {
								line.WriteByte(ch)
							}
						} else {
							// Color: map to 8 colors
							// Determine ANSI code
							// Use 30 + (r>127) + (g>127)*2 + (b>127)*4
							code := 30
							if rr > 127 { code += 1 }
							if gg > 127 { code += 2 }
							if bb > 127 { code += 4 }
							// For bright, use 1m bold? Original for red gave 31 without bold, for yellow 33, etc.
							// We'll just use code without bold, but for white, use 37
							line.WriteString(fmt.Sprintf("\x1b[%dm%c\x1b[0m", code, ch))
						}
					}
				}
			} else {
				// No colors, just char
				// Need to handle HTML escaping for html mode without colors: escape &, <, >, etc? Original may escape? For chars like <, >, &, they need to be escaped in HTML.
				// The default palette doesn't contain those, but user may provide.
				// For html without colors, we should escape.
				if cfg.html {
					// Escape for HTML
					switch ch {
					case '&':
						line.WriteString("&amp;")
					case '<':
						line.WriteString("&lt;")
					case '>':
						line.WriteString("&gt;")
					case ' ':
						// For HTML, spaces need to be preserved? In <pre>, spaces are preserved.
						// But for colors, they use &nbsp; for spaces? Let's see: For html with colors, spaces were &nbsp;?
						// In earlier test for html with colors, we didn't see spaces, but for html without colors, spaces are just spaces.
						line.WriteByte(ch)
					default:
						line.WriteByte(ch)
					}
				} else {
					line.WriteByte(ch)
				}
			}
		}
		innerLines[y] = line.String()
	}
	// Handle border
	if cfg.border {
		// For html, border is inside <pre> with + and | etc, but with html colors, border should not be colored?
		// Original for html with border and colors, border was not colored, just plain + and |
		// So we will add border after generating inner lines, without colors for border
		// For terminal with colors, border also not colored
		top := "+" + strings.Repeat("-", outW) + "+"
		bottom := top
		newLines := make([]string, 0, outH+2)
		newLines = append(newLines, top)
		for _, l := range innerLines {
			// l may contain ANSI codes or HTML spans, need to wrap with |...|
			// For html with colors, l contains spans, we need to wrap with | and |
			newLines = append(newLines, "|"+l+"|")
		}
		newLines = append(newLines, bottom)
		innerLines = newLines
		outH += 2
		outW += 2
	}
	// Now handle html wrapping
	if cfg.html && !cfg.htmlRaw {
		var htmlBuf bytes.Buffer
		htmlBuf.WriteString("<?xml version='1.0' encoding='ISO-8859-1'?>\n")
		htmlBuf.WriteString("<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n")
		htmlBuf.WriteString("<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n")
		htmlBuf.WriteString("<head>\n")
		htmlBuf.WriteString(fmt.Sprintf("<title>%s</title>\n", cfg.htmlTitle))
		htmlBuf.WriteString("<style type='text/css'>\n")
		if cfg.invert {
			htmlBuf.WriteString("body {\n   background-color: white;\n}\n")
		} else {
			htmlBuf.WriteString("body {\nbackground-color: black;\n}\n")
		}
		htmlBuf.WriteString(".ascii {\n")
		htmlBuf.WriteString("   font-family: Courier;\n")
		if !cfg.colors {
			if cfg.invert {
				htmlBuf.WriteString("   color: black;\n")
			} else {
				htmlBuf.WriteString("   color: white;\n")
			}
		}
		htmlBuf.WriteString(fmt.Sprintf("   font-size:%dpt;\n", cfg.htmlFontSize))
		if cfg.htmlNoBold {
			htmlBuf.WriteString("   font-weight: normal;\n")
		} else {
			htmlBuf.WriteString("   font-weight: bold;\n")
		}
		htmlBuf.WriteString("}\n")
		htmlBuf.WriteString("</style>\n")
		htmlBuf.WriteString("</head>\n")
		htmlBuf.WriteString("<body>\n")
		htmlBuf.WriteString("<div class='ascii'><pre>\n")
		// Content
		for i, l := range innerLines {
			if cfg.colors {
				// For html with colors, lines already contain spans, need <br/> instead of newline?
				// Original for html with colors uses <br/> at end of each line, not newline?
				// Let's check: For html with colors, the <pre> content had spans with <br/> and no extra newline between?
				// Actually we saw for html with colors, the content was "<span>...</span><br/>" per line, with no newline? But with <pre>, <br/> is used.
				htmlBuf.WriteString(l)
				if i < len(innerLines)-1 {
					htmlBuf.WriteString("<br/>")
				}
				// No extra newline? Original had newline after each <br/>? Let's add newline for readability, but original may not have newline.
				// We'll add newline after each line for consistency, but for html with colors, original had no newline, just <br/>.
				// We'll mimic: without newline, just <br/>
				if i < len(innerLines)-1 {
					htmlBuf.WriteString("\n")
				}
			} else {
				htmlBuf.WriteString(l)
				if i < len(innerLines)-1 {
					htmlBuf.WriteString("\n")
				}
			}
		}
		htmlBuf.WriteString("\n</pre>\n")
		htmlBuf.WriteString("</div>\n")
		htmlBuf.WriteString("</body>\n")
		htmlBuf.WriteString("</html>\n")
		return htmlBuf.String()
	} else if cfg.html && cfg.htmlRaw {
		// For html raw, just output inner lines with html handling
		var rawBuf bytes.Buffer
		for i, l := range innerLines {
			rawBuf.WriteString(l)
			if cfg.colors {
				if i < len(innerLines)-1 {
					rawBuf.WriteString("<br/>")
				}
			} else {
				if i < len(innerLines)-1 {
					rawBuf.WriteString("\n")
				}
			}
		}
		// For html raw without colors, need to ensure no extra newline at end? Original for raw without colors had newline after each line, including last? Let's see: For raw without colors, earlier we saw "XNMMNk0MMM\nll;l0d:Olo\n0K0MMMMMMM\n" with trailing newline. So we should add newline at end if not colors?
		if !cfg.colors {
			rawBuf.WriteString("\n")
		}
		return rawBuf.String()
	} else {
		// Plain text
		var plainBuf bytes.Buffer
		// Handle clear
		if cfg.clear {
			plainBuf.WriteString("\x1b[2J\x1b[0;0H")
		}
		for i, l := range innerLines {
			plainBuf.WriteString(l)
			if i < len(innerLines)-1 {
				plainBuf.WriteString("\n")
			}
		}
		plainBuf.WriteString("\n")
		return plainBuf.String()
	}
	// This is for non-html clear handling? Actually clear for html also prepends?
	// For html with clear, original prepended clear before html header
	// We handled clear only for plain text, need to handle for html as well
	// We'll handle clear at higher level
}

func readJPEGData(path string) ([]byte, string, error) {
	var data []byte
	var err error
	if path == "-" {
		data, err = io.ReadAll(os.Stdin)
		if err != nil {
			return nil, "", err
		}
	} else if strings.Contains(path, "://") {
		// URL
		if strings.HasPrefix(path, "file://") {
			filePath := strings.TrimPrefix(path, "file://")
			data, err = os.ReadFile(filePath)
			if err != nil {
				return nil, "Can't open " + path, err
			}
		} else {
			// Try http get
			resp, err := http.Get(path)
			if err != nil {
				return nil, "Can't open " + path, err
			}
			defer resp.Body.Close()
			if resp.StatusCode != 200 {
				return nil, "Can't open " + path, fmt.Errorf("http %d", resp.StatusCode)
			}
			data, err = io.ReadAll(resp.Body)
			if err != nil {
				return nil, "Can't open " + path, err
			}
		}
	} else {
		data, err = os.ReadFile(path)
		if err != nil {
			return nil, "Can't open " + path, err
		}
	}
	if len(data) == 0 {
		return nil, "Empty input file", fmt.Errorf("empty")
	}
	if len(data) < 2 || data[0] != 0xFF || data[1] != 0xD8 {
		return nil, fmt.Sprintf("Not a JPEG file: starts with 0x%02x 0x%02x", data[0], data[1]), fmt.Errorf("not jpeg")
	}
	return data, "", nil
}

