    f,_:=os.Open(path)
    defer f.Close()
    img,_:=jpeg.Decode(f)
    b:=img.Bounds()
    w:=b.Dx(); h:=b.Dy()
    lut:=make([][]uint8,h)
    for y:=0;y<h;y++{
        row:=make([]uint8,w)
