func main(){
    path:="assets/logo-40x25-gray.jpg"
    f,_:=os.Open(path)
    img,_:=jpeg.Decode(f)
    b:=img.Bounds()
    srcW:=40; srcH:=25
    // Get actual output for width10
    cmd:=exec.Command("./executable","--width=10",path)
    out,_:=cmd.Output()
    lines:=bytes.Split(out, []byte("\n"))
