    for i:=0;i<3;i++{ fmt.Printf("%q\n", string(lines[i])) }
    chars:=`   ...',;:clodxkO0KXNWM`
    n:=len(chars)
    // For each actual row, try to find best matching y (brute force)
    for outY:=0;outY<3;outY++{
        target:=string(lines[outY])
        bestY:=-1
        bestDist:=1000000
        bestStr:=""
        for yTest:=0;yTest<srcH;yTest++{
            var buf []byte
            for x:=0;x<10;x++{
                sx:=x*srcW/10
                r,g,bb,_:=img.At(b.Min.X+sx,b.Min.Y+yTest).RGBA()
                l:=lum(uint8(r>>8),uint8(g>>8),uint8(bb>>8))
                idx:=(int(l)*(n-1)+127)/255
                buf=append(buf, chars[idx])
