    for outY:=0;outY<3;outY++{
        target:=string(lines[outY])
        bestY:=-1
        bestDist:=1000000
        bestStr:=""
        for yTest:=0;yTest<srcH;yTest++{
            var buf []byte
            for x:=0;x<10;x++{
                sx:=int((float64(x)+0.5)*float64(srcW)/10)
                if sx>=srcW{sx=srcW-1}
                r,g,bb,_:=img.At(b.Min.X+sx,b.Min.Y+yTest).RGBA()
                l:=lum(uint8(r>>8),uint8(g>>8),uint8(bb>>8))
                idx:=(int(l)*(n-1)+127)/255
                buf=append(buf, chars[idx])
            }
            s:=string(buf)
            dist:=0
            for i:=0;i<len(s) && i<len(target);i++{ if s[i]!=target[i]{dist++}}
            if dist<bestDist{
                bestDist=dist
                bestY=yTest
                bestStr=s
            }
        }
        fmt.Printf("outY %d best y %d dist %d target %q best %q\n",outY,bestY,bestDist,target,bestStr)
    }
    // Try block averaging for Y?
    fmt.Println("--- block avg y ---")
    for outY:=0;outY<3;outY++{
        target:=string(lines[outY])
        y0:=outY*srcH/3
        y1:=(outY+1)*srcH/3
        fmt.Printf("outY %d y0 %d y1 %d\n",outY,y0,y1)
        // compute average over y0..y1 for each x
        var buf []byte
        for x:=0;x<10;x++{
            sx:=x*srcW/10
            sum:=0
            cnt:=0
            for yy:=y0;yy<y1;yy++{
