                sum:=0
                cnt:=0
                for yy:=y0;yy<y1;yy++{
                    for xx:=x0;xx<x1;xx++{
                        sum+=lumMap[yy][xx]
                        cnt++
                    }
                }
                avg:=sum/cnt
                var idx int
                switch mode{
                case "floor": idx=avg*n/256
                case "ceil": idx=(avg*n+255)/256
                case "round": idx=(avg*(n-1)+127)/255
                }
                if idx>=n{idx=n-1}
                if idx<0{idx=0}
                buf=append(buf, chars[idx])
            }
            fmt.Printf("%q\n", string(buf))
        }
    }
