package main

import (
    "os"
    "fmt"
    "image/jpeg"
    "image"
)

func main(){
    // Try to see if jp2a uses libjpeg's DCT scaling to 1/2,1/4,1/8 and then samples
    // For logo 40x25 to 10x3, they might do scaling 1/4 for width (40->10) and 1/8 for height (25->3)
    // Let's see what Go's jpeg would give if we ask libjpeg to scale? We can't, but we can simulate by averaging 4x8 blocks and then sampling?

    // But we already tried block averaging 4x8 and got NXWWW etc, not XNMM.

    // Let's try to use actual libjpeg via cgo? But we don't have headers.

    // Alternative: Use Python's Pillow to resize with different filters and see which matches jp2a's output for logo width10

    // Since we can't easily use libjpeg, let's try to brute force by using Go's image resizing with simple nearest neighbor but with different sampling offsets.

    f,_:=os.Open("assets/logo-40x25-gray.jpg")
    img,_:=jpeg.Decode(f)
    b:=img.Bounds()
    gray:=img.(*image.Gray)
    chars:=`   ...',;:clodxkO0KXNWM`
    n:=len(chars)
    // Try to find best sx mapping for width10 that is not linear but maybe they use "skip" logic: 
    // Man says "skips some X-pixels along each scanline. This gives a less precise output"
    // What does "skips some X-pixels" mean? Maybe they do: for each output row, they read a scanline, then for each output column they skip k pixels where k = srcW/outW, but they may do integer division with remainder handling via skipping?

    // Let's try to simulate: For srcW 40 outW10 step = 4 exactly, so they'd read every 4th pixel, which we did floor. But that gave MMMMMMMMMM at y=0, not XNMM.

    // So maybe they don't read y=0 for first output row; they read y at some offset like y = srcH/(2*outH) + outY*srcH/outH ?

    // Let's brute search for Y offsets that are per-row different.

    actualRows:=[]string{"XNMMNk0MMM","ll;l0d:Olo","0K0MMMMMMM"}
    srcW:=40; srcH:=25; outW:=10; outH:=3
    bestDist:=1000000
    bestYs:=[]int{}
    bestRows:=[]string{}
    // brute for all combos of y0,y1,y2
    for y0:=0;y0<srcH;y0++{
        for y1:=0;y1<srcH;y1++{
            for y2:=0;y2<srcH;y2++{
                ys:=[]int{y0,y1,y2}
                var rows []string
                totalDist:=0
                for outY:=0;outY<3;outY++{
                    sy:=ys[outY]
                    var buf []byte
                    for outX:=0;outX<10;outX++{
                        sx:=outX*srcW/outW
                        l:=gray.GrayAt(b.Min.X+sx,b.Min.Y+sy).Y
                        idx:=(int(l)*(n-1)+127)/255
                        buf=append(buf, chars[idx])
                    }
                    s:=string(buf)
                    rows=append(rows, s)
                    for i:=0;i<len(s);i++{if s[i]!=actualRows[outY][i]{totalDist++}}
                }
                if totalDist<bestDist{
                    bestDist=totalDist
                    bestYs=ys
                    bestRows=rows
                }
            }
        }
    }
    fmt.Printf("best Ys %v dist %d\n", bestYs, bestDist)
    for i,s:=range bestRows{ fmt.Printf(" row %d %q vs %q\n", i, s, actualRows[i])}

    // Now try with X offsets too: brute for x offsets per column? That would be huge.
    // Instead try to see if X sampling is also not linear: maybe they do x = (outX * srcW / outW) but with rounding to nearest, not floor, and they also handle aspect correction?

    // Let's try X sampling with rounding: (outX*srcW + outW/2)/outW
    fmt.Println("--- X rounding ---")
    for y0:=0;y0<srcH;y0++{
        for y1:=0;y1<srcH;y1++{
            for y2:=0;y2<srcH;y2++{
                ys:=[]int{y0,y1,y2}
                var rows []string
                totalDist:=0
                for outY:=0;outY<3;outY++{
                    sy:=ys[outY]
                    var buf []byte
                    for outX:=0;outX<10;outX++{
                        sx:=(outX*srcW + outW/2)/outW
