func validateConfig(cfg Config) error{
    if cfg.charsSet && len(cfg.chars)<2{return fmt.Errorf("You must specify at least two characters in --chars.")}
    if cfg.redSet||cfg.greenSet||cfg.blueSet{
        sum:=cfg.red+cfg.green+cfg.blue
        if sum<0.9999||sum>1.0001{return fmt.Errorf("Weights RED + GREEN + BLUE must equal 1.0")}
    }
    if cfg.widthSet && cfg.width<0{return fmt.Errorf("Invalid width or height specified")}
    if cfg.heightSet && cfg.height<0{return fmt.Errorf("Invalid width or height specified")}
    if cfg.heightSet && cfg.height==0{return fmt.Errorf("Invalid width or height specified")}
    if cfg.sizeSet && (cfg.sizeW<=0||cfg.sizeH<=0){return fmt.Errorf("Invalid width or height specified")}
    termNeeded:=cfg.termFit||cfg.termWidth||cfg.termHeight||cfg.termZoom
    if !cfg.widthSet && !cfg.heightSet && !cfg.sizeSet && !termNeeded{termNeeded=true}
    if termNeeded && os.Getenv("TERM")== ""{return fmt.Errorf("Environment variable TERM not set.")}
    return nil
}

func computeDimensions(cfg Config, srcW, srcH int) (int,int){
    termCols, termLines:=getTerminalSize()
    termHeight:=termLines-1
    if termHeight<1{termHeight=termLines}
    if cfg.sizeSet{return cfg.sizeW, cfg.sizeH}
    if cfg.termZoom{return termCols, termHeight}
    if cfg.termWidth{
        w:=termCols
        h:=int(float64(w)*float64(srcH)/float64(srcW)*0.5+0.5)
        if h<1{h=1}
        return w,h
    }
    if cfg.termHeight{
        h:=termHeight
        w:=int(float64(h)*float64(srcW)/float64(srcH)*2+0.5)
        if w<1{w=1}
        return w,h
    }
    if cfg.widthSet && cfg.heightSet{return cfg.width, cfg.height}
    if cfg.widthSet{
        w:=cfg.width
        if w==0{
            // fallback to termFit
            w1:=termCols; h1:=int(float64(w1)*float64(srcH)/float64(srcW)*0.5+0.5); if h1<1{h1=1}
            h2:=termHeight; w2:=int(float64(h2)*float64(srcW)/float64(srcH)*2+0.5); if w2<1{w2=1}
            fits1:=w1<=termCols && h1<=termHeight
            fits2:=w2<=termCols && h2<=termHeight
            if fits1 && fits2{
                if w1*h1>w2*h2{return w1,h1}else{return w2,h2}
            } else if fits1{return w1,h1} else if fits2{return w2,h2}
            if w1*h1<w2*h2{return w1,h1}else{return w2,h2}
        }
        h:=int(float64(w)*float64(srcH)/float64(srcW)*0.5+0.5)
        if h<1{h=1}
        return w,h
    }
    if cfg.heightSet{
        h:=cfg.height
        w:=int(float64(h)*float64(srcW)/float64(srcH)*2+0.5)
        if w<1{w=1}
        return w,h
    }
    w1:=termCols; h1:=int(float64(w1)*float64(srcH)/float64(srcW)*0.5+0.5); if h1<1{h1=1}
    h2:=termHeight; w2:=int(float64(h2)*float64(srcW)/float64(srcH)*2+0.5); if w2<1{w2=1}
    fits1:=w1<=termCols && h1<=termHeight
    fits2:=w2<=termCols && h2<=termHeight
    if fits1 && fits2{
        if w1*h1>w2*h2{return w1,h1}else{return w2,h2}
    } else if fits1{return w1,h1} else if fits2{return w2,h2}
    if w1*h1<w2*h2{return w1,h1}else{return w2,h2}
}

func processImage(cfg Config, outW, outH int, img image.Image) string{
    bounds:=img.Bounds()
    srcW:=bounds.Dx(); srcH:=bounds.Dy()
    palette:=cfg.chars
    n:=len(palette)
    innerLines:=make([]string,outH)
    for y:=0;y<outH;y++{
        var line bytes.Buffer
        for x:=0;x<outW;x++{
            srcX:= x*srcW/outW
            srcY:= y*srcH/outH
            if srcX>=srcW{srcX=srcW-1}
            if srcY>=srcH{srcY=srcH-1}
            if cfg.flipx{srcX=srcW-1-srcX}
            if cfg.flipy{srcY=srcH-1-srcY}
            r,g,b,_:=img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY).RGBA()
            rr:=uint8(r>>8); gg:=uint8(g>>8); bb:=uint8(b>>8)
            lum:=uint8(cfg.red*float64(rr)+cfg.green*float64(gg)+cfg.blue*float64(bb)+0.5)
            idx:=(int(lum)*(n-1)+127)/255
            if idx<0{idx=0}; if idx>=n{idx=n-1}
            if cfg.invert{idx=n-1-idx}
            ch:=palette[idx]
            if cfg.colors{
                if cfg.html{
                    var hexColor, textColor string
                    if cfg.grayscale{
                        hexColor=fmt.Sprintf("#%02x%02x%02x", lum, lum, lum)
                        textColor=fmt.Sprintf("#%02x%02x%02x", lum/2, lum/2, lum/2)
                    } else {
                        hexColor=fmt.Sprintf("#%02x%02x%02x", rr, gg, bb)
                        textColor=fmt.Sprintf("#%02x%02x%02x", rr/2, gg/2, bb/2)
                    }
                    // For grayscale image with colors, the original used 33m etc? But for html we use hex
                    // For html without fill, only color, no background
                    // For html with fill, need background too, but we need to decide textColor vs hexColor
                    // Observed for html with fill and grayscale, textColor is half lum, background is hexColor, but they used style 'color:#6d6d6d; background-color:#dadada;'
                    // For html with fill and color, we need to use half of RGB for text?
                    // We'll handle:
                    if cfg.fill{
                        // Check if grayscale or color, text is half, background is hex
                        // For html fill, they also use color for text as half of original
                        // For non-grayscale color image, textColor should be half of original RGB, but observed for color image with html fill, not tested yet.
                        line.WriteString(fmt.Sprintf("<span style='color:%s; background-color:%s;'>%c</span>", textColor, hexColor, ch))
                    } else {
                        line.WriteString(fmt.Sprintf("<span style='color:%s;'>%c</span>", hexColor, ch))
                    }
                    // Escape for html? The ch may be <>&, need to escape inside span? But original for colors, they didn't escape? Let's assume same as plain
                    // Actually for html with colors, they still escape? For chars like <, they would be inside span, but should be escaped.
                    // We'll handle after.
                } else {
                    if cfg.grayscale{
                        line.WriteString(fmt.Sprintf("\x1b[37m%c\x1b[0m", ch))
                    } else {
                        if rr==gg && gg==bb{
                            if lum>127{
                                line.WriteString(fmt.Sprintf("\x1b[1m%c\x1b[0m", ch))
                            } else {
                                line.WriteByte(ch)
                            }
                        } else {
                            code:=30
                            if rr>127{code+=1}
                            if gg>127{code+=2}
                            if bb>127{code+=4}
                            line.WriteString(fmt.Sprintf("\x1b[%dm%c\x1b[0m", code, ch))
                        }
                    }
                }
            } else {
                if cfg.html{
                    if ch=='&'{line.WriteString("&amp.") // Actually "&amp;" ?
                        // Original for html without colors, they may output raw char but need escaping.
                        // For space, they keep as space, but for html with colors, spaces become &nbsp;? Let's check.
                        // Earlier we saw for html with colors, there was no space handling, but they may use &nbsp; for spaces?
                        // We haven't tested spaces in html. Let's assume for now we handle & < >.

                    }
                    switch ch{
                    case '&':line.WriteString("&amp;")
                    case '<':line.WriteString("&lt;")
                    case '>':line.WriteString("&gt;")
                    case ' ':line.WriteByte(' ') // keep space, but for html with colors, they used &nbsp; for space? Check earlier: For html with colors, we saw no space test. Let's keep space.
                    default:line.WriteByte(ch)
                    }
                } else {
                    line.WriteByte(ch)
                }
            }
        }
        innerLines[y]=line.String()
    }
    // Fix the earlier broken escape for '&' - we added extra WriteString before switch, remove it
    // Actually we need to handle that we already wrote for html colors case, so not needed

    if cfg.border{
        top:="+"+strings.Repeat("-",outW)+"+"
        bottom:=top
        newLines:=make([]string,0,outH+2)
        newLines=append(newLines, top)
        for _,l:=range innerLines{
            newLines=append(newLines, "|"+l+"|")
        }
        newLines=append(newLines, bottom)
        innerLines=newLines
        outH+=2
        outW+=2
    }
    if cfg.html && !cfg.htmlRaw{
        var htmlBuf bytes.Buffer
        htmlBuf.WriteString("<?xml version='1.0' encoding='ISO-8859-1'?>\n")
        htmlBuf.WriteString("<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n")
        htmlBuf.WriteString("<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n")
        htmlBuf.WriteString("<head>\n")
        htmlBuf.WriteString(fmt.Sprintf("<title>%s</title>\n", cfg.htmlTitle))
        htmlBuf.WriteString("<style type='text/css'>\n")
        if cfg.invert{
            htmlBuf.WriteString("body {\n   background-color: white;\n}\n")
        } else {
            htmlBuf.WriteString("body {\nbackground-color: black;\n}\n")
        }
        htmlBuf.WriteString(".ascii {\n")
        htmlBuf.WriteString("   font-family: Courier;\n")
        if !cfg.colors{
            if cfg.invert{
                htmlBuf.WriteString("   color: black;\n")
            } else {
                htmlBuf.WriteString("   color: white;\n")
            }
        }
        htmlBuf.WriteString(fmt.Sprintf("   font-size:%dpt;\n", cfg.htmlFontSize))
        if cfg.htmlNoBold{
            htmlBuf.WriteString("   font-weight: normal;\n")
        } else {
            htmlBuf.WriteString("   font-weight: bold;\n")
        }
        htmlBuf.WriteString("}\n")
        htmlBuf.WriteString("</style>\n")
        htmlBuf.WriteString("</head>\n")
        htmlBuf.WriteString("<body>\n")
        htmlBuf.WriteString("<div class='ascii'><pre>\n")
        for i,l:=range innerLines{
            if cfg.colors{
                htmlBuf.WriteString(l)
                if i < len(innerLines)-1{htmlBuf.WriteString("<br/>")}
                if i < len(innerLines)-1{htmlBuf.WriteString("\n")}
            } else {
                htmlBuf.WriteString(l)
                if i < len(innerLines)-1{htmlBuf.WriteString("\n")}
            }
        }
        htmlBuf.WriteString("\n</pre>\n")
        htmlBuf.WriteString("</div>\n")
        htmlBuf.WriteString("</body>\n")
        htmlBuf.WriteString("</html>\n")
        // Handle clear for html
        if cfg.clear{
            return "\x1b[2J\x1b[0;0H" + htmlBuf.String()
        }
        return htmlBuf.String()
    } else if cfg.html && cfg.htmlRaw{
        var rawBuf bytes.Buffer
        for i,l:=range innerLines{
            rawBuf.WriteString(l)
            if cfg.colors{
                if i < len(innerLines)-1{rawBuf.WriteString("<br/>")}
                if i < len(innerLines)-1{rawBuf.WriteString("\n")}
            } else {
                if i < len(innerLines)-1{rawBuf.WriteString("\n")}
            }
        }
        if !cfg.colors{
            rawBuf.WriteString("\n")
        }
        if cfg.clear{
            return "\x1b[2J\x1b[0;0H" + rawBuf.String()
        }
        return rawBuf.String()
    } else {
        var plainBuf bytes.Buffer
        if cfg.clear{
            plainBuf.WriteString("\x1b[2J\x1b[0;0H")
        }
        for i,l:=range innerLines{
            plainBuf.WriteString(l)
            if i < len(innerLines)-1{plainBuf.WriteString("\n")}
        }
        plainBuf.WriteString("\n")
        return plainBuf.String()
    }
}

func readJPEGData(path string) ([]byte, string, error){
    var data []byte
    var err error
    if path=="-"{data,err=io.ReadAll(os.Stdin); if err!=nil{return nil,"",err}
    } else if strings.Contains(path,"://"){
        if strings.HasPrefix(path,"file://"){
            fp:=strings.TrimPrefix(path,"file://")
            data,err=os.ReadFile(fp)
            if err!=nil{return nil,"Can't open "+path,err}
        } else {
            resp,err2:=http.Get(path)
            if err2!=nil{return nil,"Can't open "+path,err2}
            defer resp.Body.Close()
            if resp.StatusCode!=200{return nil,"Can't open "+path,fmt.Errorf("http %d",resp.StatusCode)}
            data,err=io.ReadAll(resp.Body)
            if err!=nil{return nil,"Can't open "+path,err}
        }
    } else {
        data,err=os.ReadFile(path)
        if err!=nil{return nil,"Can't open "+path,err}
    }
    if len(data)==0{return nil,"Empty input file",fmt.Errorf("empty")}
    if len(data)<2 || data[0]!=0xFF || data[1]!=0xD8{
        return nil,fmt.Sprintf("Not a JPEG file: starts with 0x%02x 0x%02x",data[0],data[1]),fmt.Errorf("not jpeg")
    }
    return data,"",nil
}

func main(){
    cfg, files, err:=parseArgs(os.Args[1:])
    if err!=nil{
        fmt.Fprintln(os.Stderr, err.Error())
        fmt.Fprintln(os.Stderr, "")
        fmt.Fprintln(os.Stderr, versionStr)
        fmt.Fprintln(os.Stderr, "")
        fmt.Fprintln(os.Stderr, helpStr)
        os.Exit(1)
    }
    if err:=validateConfig(cfg); err!=nil{
        fmt.Fprintln(os.Stderr, err.Error())
        os.Exit(1)
    }
    if len(files)==0{
        fmt.Fprintln(os.Stderr, "No files specified.")
        fmt.Fprintln(os.Stderr, "")
        fmt.Fprintln(os.Stderr, versionStr)
        fmt.Fprintln(os.Stderr, "")
        fmt.Fprintln(os.Stderr, helpStr)
        os.Exit(1)
    }
    var outWriter io.Writer=os.Stdout
    var outFile *os.File
    if cfg.outputSet{
        if cfg.output=="-"{outWriter=os.Stdout}else{
            f,err:=os.Create(cfg.output)
            if err!=nil{fmt.Fprintf(os.Stderr,"Can't open %s\n",cfg.output); os.Exit(1)}
            defer f.Close()
            outWriter=f
            outFile=f
        }
    }
    hasError:=false
    successCount:=0
    for _,path:=range files{
        data,errMsg,err:=readJPEGData(path)
        if err!=nil{fmt.Fprintln(os.Stderr,errMsg); hasError=true; continue}
        img,err:=jpeg.Decode(bytes.NewReader(data))
        if err!=nil{fmt.Fprintln(os.Stderr,"Can't open "+path); hasError=true; continue}
        bounds:=img.Bounds()
        srcW:=bounds.Dx(); srcH:=bounds.Dy()
        colorComponents:=3
        switch img.(type){
        case *image.Gray:*image.Gray16:colorComponents=1
        default:colorComponents=3
        }
        outW,outH:=computeDimensions(cfg, srcW, srcH)
        if cfg.verbose{
            fmt.Fprintf(os.Stderr,"File: %s\n",path)
            fmt.Fprintf(os.Stderr,"Source width: %d\n",srcW)
            fmt.Fprintf(os.Stderr,"Source height: %d\n",srcH)
            fmt.Fprintf(os.Stderr,"Source color components: %d\n",colorComponents)
            fmt.Fprintf(os.Stderr,"Output width: %d\n",outW)
            fmt.Fprintf(os.Stderr,"Output height: %d\n",outH)
            fmt.Fprintf(os.Stderr,"Output palette (%d chars): '%s'\n",len(cfg.chars),cfg.chars)
            for y:=0;y<srcH;y++{
                hashes:=(y+1)*56/srcH
                if hashes>56{hashes=56}
                dots:=56-hashes
                bar:=strings.Repeat("#",hashes)+strings.Repeat(".",dots)
                // For last line, ensure full hashes
                if y==srcH-1{bar=strings.Repeat("#",56)}
                fmt.Fprintf(os.Stderr,"Decompressing image [%s]\r",bar)
                if y==srcH-1{fmt.Fprintf(os.Stderr,"\n")}
            }
        }
        result:=processImage(cfg,outW,outH,img)
        fmt.Fprint(outWriter,result)
        if outFile!=nil{_ = outFile}
        successCount++
    }
    if hasError && successCount==0{os.Exit(1)}
}
GO
