        if arg=="-x"||arg=="--flipx"{cfg.flipx=true; continue}
        if arg=="-y"||arg=="--flipy"{cfg.flipy=true; continue}
        if arg=="-f"||arg=="--term-fit"{cfg.termFit=true; continue}
        if arg=="-z"||arg=="--term-zoom"{cfg.termZoom=true; continue}
        if arg=="-v"||arg=="--verbose"{cfg.verbose=true; continue}
        if arg=="-d"||arg=="--debug"{cfg.debug=true; continue}
        if arg=="-h"||arg=="--help"{printHelp(); os.Exit(0)}
        if arg=="-V"||arg=="--version"{printVersion(); os.Exit(0)}
        if strings.HasPrefix(arg,"--background="){
            val:=strings.TrimPrefix(arg,"--background=")
            if val=="dark"{cfg.invert=false}else if val=="light"{cfg.invert=true}else{return cfg,nil,fmt.Errorf("Unknown option %s",arg)}
            continue
        }
        if strings.HasPrefix(arg,"--chars="){cfg.chars=strings.TrimPrefix(arg,"--chars="); cfg.charsSet=true; continue}
        if arg=="--colors"{cfg.colors=true; continue}
        if arg=="--fill"||arg=="--html-fill"{cfg.fill=true; continue}
        if arg=="--grayscale"{cfg.grayscale=true; continue}
        if strings.HasPrefix(arg,"--green="){
            val:=strings.TrimPrefix(arg,"--green=")
            f,err:=strconv.ParseFloat(val,64)
            if err!=nil{return cfg,nil,fmt.Errorf("Unknown option %s",arg)}
            cfg.green=f; cfg.greenSet=true; continue
        }
        if strings.HasPrefix(arg,"--height="){
            val:=strings.TrimPrefix(arg,"--height=")
            n,err:=strconv.Atoi(val)
            if err!=nil{return cfg,nil,fmt.Errorf("Unknown option %s",arg)}
            cfg.height=n; cfg.heightSet=true; continue
        }
        if arg=="--html"{cfg.html=true; continue}
        if arg=="--html-no-bold"{cfg.htmlNoBold=true; continue}
        if arg=="--html-raw"{cfg.htmlRaw=true; continue}
        if strings.HasPrefix(arg,"--html-fontsize="){
            val:=strings.TrimPrefix(arg,"--html-fontsize=")
            n,err:=strconv.Atoi(val)
            if err!=nil{return cfg,nil,fmt.Errorf("Unknown option %s",arg)}
            cfg.htmlFontSize=n; cfg.htmlFontSizeSet=true; continue
        }
        if strings.HasPrefix(arg,"--html-title="){
            cfg.htmlTitle=strings.TrimPrefix(arg,"--html-title=")
            cfg.htmlTitleSet=true; continue
        }
        if strings.HasPrefix(arg,"--output="){
            cfg.output=strings.TrimPrefix(arg,"--output=")
            cfg.outputSet=true; continue
        }
        if strings.HasPrefix(arg,"--red="){
            val:=strings.TrimPrefix(arg,"--red=")
            f,err:=strconv.ParseFloat(val,64)
            if err!=nil{return cfg,nil,fmt.Errorf("Unknown option %s",arg)}
            cfg.red=f; cfg.redSet=true; continue
        }
        if strings.HasPrefix(arg,"--blue="){
            val:=strings.TrimPrefix(arg,"--blue=")
            f,err:=strconv.ParseFloat(val,64)
            if err!=nil{return cfg,nil,fmt.Errorf("Unknown option %s",arg)}
            cfg.blue=f; cfg.blueSet=true; continue
        }
        if strings.HasPrefix(arg,"--size="){
            val:=strings.TrimPrefix(arg,"--size=")
            parts:=strings.Split(val,"x")
            if len(parts)!=2{return cfg,nil,fmt.Errorf("Unknown option %s",arg)}
            w,err1:=strconv.Atoi(parts[0])
